from rules import POLICY, active_dependencies, acyclic


def solve(data):
    packages = data["packages"]
    names = sorted(packages, reverse=POLICY["name_order"] == "descending")
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]

    rows_by_version = {
        name: {row["version"]: row for row in rows}
        for name, rows in packages.items()
    }
    domains = []
    for name in names:
        versions = sorted(rows_by_version[name])
        domains.append([None] + versions)

    best = None
    best_vector = None
    for values in product(*domains):
        chosen = dict(zip(names, values))
        installed = {name: version for name, version in chosen.items() if version is not None}

        valid = True
        for name, bounds in roots.items():
            version = installed.get(name)
            if version is None or not (bounds[0] <= version <= bounds[1]):
                valid = False
                break
        if not valid:
            continue

        edges = {}
        for name, version in installed.items():
            if version in blocked.get(name, ()):
                valid = False
                break
            if name in pins and version != pins[name]:
                valid = False
                break
            edges[name] = []
            row = rows_by_version[name][version]
            for dep in active_dependencies(row, features):
                target = dep["name"]
                target_version = installed.get(target)
                if target_version is None or not (dep["min"] <= target_version <= dep["max"]):
                    valid = False
                    break
                edges[name].append(target)
            if not valid:
                break
        if not valid or not acyclic(edges):
            continue

        # Reject packages that are installed but are not in the roots' closure.
        reachable = set()
        pending = list(roots)
        while pending:
            name = pending.pop()
            if name in reachable:
                continue
            reachable.add(name)
            pending.extend(edges.get(name, ()))
        if reachable != set(installed):
            continue

        vector = tuple(-1 if chosen[name] is None else chosen[name] for name in names)
        if best_vector is None or vector < best_vector:
            best_vector = vector
            best = installed

    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best}
