def active_dependencies(row, features):
    return [
        dependency
        for dependency in row.get("deps", [])
        if not dependency.get("feature") or dependency.get("feature") in features
    ]


def acyclic(edges):
    finished = set()
    active = set()

    def visit(name):
        if name in active:
            return False
        if name in finished:
            return True
        active.add(name)
        for other in edges.get(name, ()):
            if not visit(other):
                return False
        active.remove(name)
        finished.add(name)
        return True

    return all(visit(name) for name in edges)
